<x-dashboard-layout title="Alerts"><div class="operations-page" x-data="{createOpen:{{ $errors->any()?'true':'false' }}}"><div class="page-heading"><div><p class="breadcrumb">Operations / Alerts</p><h1>Alerts & incidents</h1><p>Detect failures and resource pressure before users are affected.</p></div><div class="heading-actions"><a href="{{ route('alerts.index',request()->query()) }}" class="button button--secondary"><i data-lucide="refresh-cw"></i> Refresh</a><button class="button button--primary" @click="createOpen=true"><i data-lucide="plus"></i> Create alert</button></div></div><div class="alerts-layout"><main><section class="card incident-list"><div class="card-head"><div><h2>Incident history</h2><p>Triggered, acknowledged, and resolved alerts.</p></div></div><form class="alerts-reference-filters" method="get" action="{{ route('alerts.index') }}"><label class="filter-select"><span class="visually-hidden">Status</span><select name="status" onchange="this.form.submit()"><option value="" @selected(request('status')===''||request('status')===null)>All statuses</option><option value="open" @selected(request('status')==='open')>Open</option><option value="acknowledged" @selected(request('status')==='acknowledged')>Acknowledged</option><option value="resolved" @selected(request('status')==='resolved')>Resolved</option></select><i data-lucide="chevron-down"></i></label><label class="filter-select"><span class="visually-hidden">Severity</span><select name="severity" onchange="this.form.submit()"><option value="" @selected(request('severity')===''||request('severity')===null)>All severities</option><option value="warning" @selected(request('severity')==='warning')>Warning</option><option value="error" @selected(request('severity')==='error')>Error</option><option value="critical" @selected(request('severity')==='critical')>Critical</option></select><i data-lucide="chevron-down"></i></label><label class="filter-select"><span class="visually-hidden">Server</span><select na